                if (stroke === "#10b981") el.setAttribute("stroke", "#047857");
                
                if (fill.includes("rgba(245, 158, 11")) el.setAttribute("fill", "#fef3c7");
                if (stroke === "#f59e0b") el.setAttribute("stroke", "#b45309");

                if (fill === "#1e293b") el.setAttribute("fill", "#f8fafc");
