                if (stroke === "#f59e0b") c.setAttribute("stroke", "#b45309");

                if (fill === "#1e293b") c.setAttribute("fill", "#f8fafc");
                if (stroke === "#475569" || stroke === "#64748b") c.setAttribute("stroke", "#cbd5e1");
                
                if (stroke === "#ffffff") c.setAttribute("stroke", "#94a3b8");
